def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = DAILY_SALARY * 0.28
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.55
        return float(min(budget, base))

    prev_bids = []
    threat_bids = []
    eric_bid = None
    active_count = 0

    for oid, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        active_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 0) > 0 and opp.get('budget', 0) > 0:
                threat_bids.append(float(bid))
        if oid == 'Eric' and bid is not None:
            eric_bid = float(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    threat_prev = max(threat_bids) if threat_bids else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.55
    elif hp <= 4:
        danger += 0.35
    elif hp <= 6:
        danger += 0.18
    if no_water_days >= 2:
        danger += 0.35
    elif no_water_days >= 1:
        danger += 0.18
    danger += 0.22 * scarcity
    if day >= 8:
        danger += 0.08

    target = DAILY_SALARY * (0.34 + 0.18 * scarcity)

    if eric_bid is not None:
        if danger >= 0.75:
            target = max(target, eric_bid + 2.0)
        elif danger >= 0.45:
            target = max(target, eric_bid * 0.78)
        else:
            target = max(target, eric_bid * 0.42)
    elif threat_prev > 0:
        if danger >= 0.75:
            target = max(target, threat_prev + 1.5)
        elif danger >= 0.45:
            target = max(target, threat_prev * 0.72)
        else:
            target = max(target, threat_prev * 0.4)

    if active_count >= 3 and supply <= 17:
        target += 8.0
    elif active_count <= 1:
        target *= 0.72

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    max_today = budget
    if budget > reserve_floor:
        max_today = budget - reserve_floor * 0.15

    if hp <= 2 or no_water_days >= 2:
        max_today = budget

    bid = min(max_today, target)
    bid = max(0.0, bid)

    if bid < 1.0 and budget >= 1.0:
        bid = 1.0

    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # If very low HP, prioritize survival over budget efficiency.
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer how aggressively others are competing.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline: mid bid to beat underbidders but not overpay.
    # Supply is between 15 and 25; higher supply reduces urgency.
    supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)  # 0..1
    urgency = 1.0 - max(0.0, min(1.0, supply_factor))

    # Estimate competitive pressure from yesterday's high bid.
    comp_pressure = 0.0
    if prev_bids:
        comp_pressure = max(prev_bids)

    # If someone previously paid very high, we should raise bid; otherwise hold mid-high.
    # Use DAILY_SALARY as a reference scale.
    high_threshold = DAILY_SALARY * 0.85

    if my_hp <= 2.0:
        target = DAILY_SALARY * (0.9 - 0.2 * urgency)
    elif comp_pressure >= high_threshold:
        # Others were very aggressive; match their intensity but keep some budget.
        target = DAILY_SALARY * (0.7 + 0.2 * urgency)
    else:
        # Mix: slightly above mid to avoid being outbid by aggressive survivors.
        target = DAILY_SALARY * (0.55 + 0.15 * urgency)

    # Clamp by budget.
    bid = min(my_budget, target)

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    # Small deterministic bump on later days to avoid endgame starvation.
    try:
        if int(day) >= 7:
            bid = min(my_budget, bid + DAILY_SALARY * 0.05)
    except Exception:
        pass

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.98)

    if my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.9
    else:
        base_bid = DAILY_SALARY * 0.7
        if highest_prev_bid > 0:
            if highest_prev_bid > DAILY_SALARY * 0.8:
                 base_bid = max(base_bid, highest_prev_bid + 1)
                 base_bid = min(base_bid, DAILY_SALARY * 0.95)
            else:
                base_bid = max(base_bid, highest_prev_bid * 1.05)
                base_bid = min(base_bid, DAILY_SALARY * 0.8)

    normalized_supply = (day_context['supply'] - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    scarcity_factor = 1 - normalized_supply
    supply_adjustment = scarcity_factor * (DAILY_SALARY * 0.1)
    final_bid = base_bid + supply_adjustment

    normalized_day = day_context['day'] / EPISODE_DAYS
    day_adjustment = normalized_day * (DAILY_SALARY * 0.1)
    final_bid = final_bid + day_adjustment

    final_bid = min(my_status['budget'], final_bid, DAILY_SALARY * 0.99)

    final_bid = max(final_bid, 1.0)

    return final_bid

